// ============================================================
// TRIAL VERSION #1 - GRAND MASTER FILE
//
// Includes in ONE TXT:
// 1) Combined Visual Development System
//    - Firelit Room visual panel
//    - Outside/Village visual panel
//    - Dusty Path character + armour + health
//
// 2) Flight Crystal Map System
//    - adds one custom "$" shrine to the world map
//    - obtaining the crystal permanently unlocks flight
//    - adds Flight ON/OFF on A Dusty Path
//
// Notes:
// - The normal sulphur mine remains marked with "S".
// - The custom Flight Crystal shrine uses "$".
// ============================================================

// ============================================================
// TRIAL VERSION #1 - COMBINED VISUAL DEVELOPMENT SYSTEM
//
// Combines:
// 1) Character Dev Final V#1
// 2) Firelit_Room Dev Final V1
// 3) Village Growth Display
//
// ONE shared left-side panel:
// - A Firelit Room  -> fire image + state + temperature + spread risk
// - Outside/Village -> village growth image + village statistics
// - A Dusty Path    -> wanderer + armour selector + health
//
// This version uses compressed panel-sized artwork so it is much
// smaller and easier to paste into Opera GX DevTools.
//
// Remove everything with:
// removeTrialVersion1CombinedVisuals()
//
// Character helper:
// setTrialVersion1Armour("base" | "leather" | "iron" | "steel")
//
// Village test helper:
// setTrialVillageStage("auto" | 1 | 2 | 3 | 4)
// ============================================================

(function () {
    "use strict";

    // --------------------------------------------------------
    // Remove older separate versions first
    // --------------------------------------------------------
    [
        "removeTrialVersion1CombinedVisuals",
        "removeTrialVersion1ArmourCharacter",
        "removeTrialVersion1FireRoomDisplay",
        "removeTrialVersion1VillageDisplay",
        "removeTrialDustyWanderer",
        "removeTrialDustyWandererV2",
        "removeTrialPathArmourSelector",
        "removeTrialVersion1FlightCrystal"
    ].forEach(function (fn) {
        try {
            if (typeof window[fn] === "function") {
                window[fn]();
            }
        } catch (e) {}
    });

    if (window.TrialVersion1CombinedVisualsInstalled) {
        console.log("Trial Version #1 Combined Visuals already installed.");
        return;
    }

    if (typeof window.$ === "undefined" ||
        typeof window.$SM === "undefined" ||
        typeof window.Engine === "undefined" ||
        typeof window.Room === "undefined" ||
        typeof window.Outside === "undefined" ||
        typeof window.Path === "undefined" ||
        typeof window.World === "undefined") {
        console.error("A Dark Room has not finished loading yet.");
        return;
    }

    window.TrialVersion1CombinedVisualsInstalled = true;

    var $ = window.$;
    var $SM = window.$SM;
    var Engine = window.Engine;
    var Room = window.Room;
    var Outside = window.Outside;
    var Path = window.Path;
    var World = window.World;

    // --------------------------------------------------------
    // Embedded compressed artwork
    // --------------------------------------------------------
    var CHARACTER_IMAGES = {
        base: "data:image/webp;base64,",
        leather: "data:image/webp;base64,",
        iron: "data:image/webp;base64,",
        steel: "data:image/webp;base64,"
    };

    var FIRE_IMAGES = {
        out: "data:image/webp;base64,",
        flickering: "data:image/webp;base64,",
        roaring: "data:image/webp;base64,"
    };

    var VILLAGE_IMAGES = {
        1: "data:image/webp;base64,",
        2: "data:image/webp;base64,",
        3: "data:image/webp;base64,",
        4: "data:image/webp;base64,"
    };

    // ========================================================
    // SHARED PANEL
    // ========================================================
    function createSharedPanel() {
        if (document.getElementById("trial-v1-shared-panel")) return;

        var panel = document.createElement("div");
        panel.id = "trial-v1-shared-panel";

        Object.assign(panel.style, {
            position: "fixed",
            left: "18px",
            top: "85px",
            width: "245px",
            height: "690px",
            boxSizing: "border-box",
            padding: "8px",
            background: "rgba(255,255,255,0.96)",
            border: "1px solid #555",
            zIndex: "9999",
            textAlign: "center",
            fontFamily: "Georgia, serif",
            color: "#222",
            display: "none",
            overflow: "hidden"
        });

        var title = document.createElement("div");
        title.id = "trial-v1-shared-title";
        Object.assign(title.style, {
            fontWeight: "bold",
            fontSize: "19px",
            marginBottom: "4px"
        });

        var image = document.createElement("img");
        image.id = "trial-v1-shared-image";
        Object.assign(image.style, {
            width: "100%",
            height: "535px",
            objectFit: "contain",
            display: "block",
            margin: "0 auto"
        });

        var info = document.createElement("div");
        info.id = "trial-v1-shared-info";

        var riskBar = document.createElement("div");
        riskBar.id = "trial-v1-fire-risk-bar";
        Object.assign(riskBar.style, {
            width: "100%",
            height: "8px",
            border: "1px solid #555",
            marginTop: "4px",
            boxSizing: "border-box",
            display: "none"
        });

        var riskFill = document.createElement("div");
        riskFill.id = "trial-v1-fire-risk-fill";
        Object.assign(riskFill.style, {
            width: "0%",
            height: "100%",
            background: "#555"
        });

        riskBar.appendChild(riskFill);
        panel.appendChild(title);
        panel.appendChild(image);
        panel.appendChild(info);
        panel.appendChild(riskBar);
        document.body.appendChild(panel);
    }

    function infoLine(text, bold) {
        var div = document.createElement("div");
        div.textContent = text;
        Object.assign(div.style, {
            fontSize: "13px",
            marginTop: "3px",
            fontWeight: bold ? "bold" : "normal"
        });
        return div;
    }

    function setPanel(titleText, imageUri, lines, showRisk, riskPercent) {
        createSharedPanel();

        var panel = document.getElementById("trial-v1-shared-panel");
        var title = document.getElementById("trial-v1-shared-title");
        var image = document.getElementById("trial-v1-shared-image");
        var info = document.getElementById("trial-v1-shared-info");
        var bar = document.getElementById("trial-v1-fire-risk-bar");
        var fill = document.getElementById("trial-v1-fire-risk-fill");

        panel.style.display = "block";
        title.textContent = titleText;

        if (image.dataset.uri !== imageUri) {
            image.src = imageUri;
            image.dataset.uri = imageUri;
        }

        info.innerHTML = "";
        lines.forEach(function (line, i) {
            info.appendChild(infoLine(line, i === 0));
        });

        if (showRisk) {
            bar.style.display = "block";
            fill.style.width = Math.max(0, Math.min(100, riskPercent || 0)) + "%";
        } else {
            bar.style.display = "none";
        }
    }

    function hidePanel() {
        var panel = document.getElementById("trial-v1-shared-panel");
        if (panel) panel.style.display = "none";
    }

    // ========================================================
    // CHARACTER / ARMOUR
    // ========================================================
    var ARMOURS = [
        { mode: "base", item: null, label: "none", characterLabel: "base clothing", hp: 10 },
        { mode: "leather", item: "l armour", label: "leather", characterLabel: "leather armour", hp: 15 },
        { mode: "iron", item: "i armour", label: "iron", characterLabel: "iron armour", hp: 25 },
        { mode: "steel", item: "s armour", label: "steel", characterLabel: "steel armour", hp: 45 }
    ];

    function storeAmount(item) {
        if (!item) return 1;
        try {
            return Number($SM.get('stores["' + item + '"]') || 0);
        } catch (e) {
            return 0;
        }
    }

    function availableArmours() {
        return ARMOURS.filter(function (a) {
            return a.mode === "base" || storeAmount(a.item) > 0;
        });
    }

    function strongestOwnedArmour() {
        var list = availableArmours();
        return list.length ? list[list.length - 1].mode : "base";
    }

    function armourInfo(mode) {
        for (var i = 0; i < ARMOURS.length; i++) {
            if (ARMOURS[i].mode === mode) return ARMOURS[i];
        }
        return ARMOURS[0];
    }

    window.TrialVersion1SelectedArmour =
        window.TrialVersion1SelectedArmour || strongestOwnedArmour();

    function currentArmour() {
        var info = armourInfo(window.TrialVersion1SelectedArmour);

        if (info.item && storeAmount(info.item) <= 0) {
            window.TrialVersion1SelectedArmour = strongestOwnedArmour();
            info = armourInfo(window.TrialVersion1SelectedArmour);
        }
        return info;
    }

    var originalGetMaxHealth = World.getMaxHealth;

    if (typeof originalGetMaxHealth === "function") {
        World.getMaxHealth = function () {
            return currentArmour().hp;
        };
    }

    function currentHealth() {
        var max = currentArmour().hp;
        var current = max;

        try {
            if (typeof World.health === "number") current = World.health;
            else if (World.state && typeof World.state.health === "number") current = World.state.health;
            else if (World.state && typeof World.state.hp === "number") current = World.state.hp;
        } catch (e) {}

        if (!isFinite(current)) current = max;
        return Math.max(0, Math.min(current, max));
    }

    function findArmourRow() {
        var panel = $("#pathPanel");
        if (!panel.length) return null;

        var key = panel.find(".row_key").filter(function () {
            return $(this).text().trim().toLowerCase() === "armour";
        }).first();

        if (key.length) return key.parent();

        var result = null;
        panel.find("*").each(function () {
            var el = $(this);
            var own = el.clone().children().remove().end().text().trim().toLowerCase();
            if (own === "armour") {
                result = el.parent();
                return false;
            }
        });

        return result;
    }

    function makeChevron(direction) {
        var c = document.createElement("span");
        Object.assign(c.style, {
            width: "9px",
            height: "9px",
            display: "inline-block",
            cursor: "pointer",
            margin: "0 6px",
            boxSizing: "border-box",
            borderTop: "2px solid #222",
            borderRight: "2px solid #222",
            userSelect: "none"
        });
        c.style.transform = direction < 0 ? "rotate(-135deg)" : "rotate(45deg)";
        c.addEventListener("click", function (e) {
            e.preventDefault();
            e.stopPropagation();
            cycleArmour(direction);
        });
        return c;
    }

    function cycleArmour(direction) {
        var list = availableArmours();
        var current = currentArmour().mode;
        var i = list.findIndex(function (a) { return a.mode === current; });
        if (i < 0) i = 0;
        i = (i + direction + list.length) % list.length;
        window.TrialVersion1SelectedArmour = list[i].mode;
        refreshArmourControl();
    }

    function refreshArmourControl() {
        var row = findArmourRow();
        if (!row || !row.length) return;

        var control = document.getElementById("trial-v1-combined-armour-control");

        if (!control) {
            row.find(".row_val").first().css("visibility", "hidden")
                .attr("data-trial-combined-hidden", "true");

            control = document.createElement("span");
            control.id = "trial-v1-combined-armour-control";
            Object.assign(control.style, {
                float: "right",
                display: "inline-flex",
                alignItems: "center",
                minWidth: "105px"
            });

            var left = makeChevron(-1);
            var value = document.createElement("span");
            value.id = "trial-v1-combined-armour-value";
            Object.assign(value.style, {
                minWidth: "52px",
                textAlign: "center"
            });
            var right = makeChevron(1);

            control.appendChild(left);
            control.appendChild(value);
            control.appendChild(right);
            row.append(control);
        }

        var valueEl = document.getElementById("trial-v1-combined-armour-value");
        if (valueEl) valueEl.textContent = currentArmour().label;
    }

    window.setTrialVersion1Armour = function (mode) {
        mode = String(mode || "").toLowerCase();

        if (!["base", "leather", "iron", "steel"].includes(mode)) {
            console.error('Use "base", "leather", "iron", or "steel".');
            return;
        }

        var info = armourInfo(mode);
        if (info.item && storeAmount(info.item) <= 0) {
            console.error("You do not own " + info.label + " armour.");
            return;
        }

        window.TrialVersion1SelectedArmour = mode;
        refreshArmourControl();
    };

    function renderCharacter() {
        refreshArmourControl();
        var a = currentArmour();

        setPanel(
            "wanderer",
            CHARACTER_IMAGES[a.mode],
            [
                a.characterLabel,
                "health: " + Math.round(currentHealth()) + " / " + Math.round(a.hp)
            ],
            false,
            0
        );
    }

    // ========================================================
    // FIRELIT ROOM
    // ========================================================
    function fireText() {
        try {
            var t = $SM.get("game.fire.text");
            if (typeof t === "string") return t.trim().toLowerCase();
        } catch (e) {}
        return "out";
    }

    function fireValue() {
        try {
            var v = Number($SM.get("game.fire.value"));
            if (isFinite(v)) return Math.max(0, Math.min(4, v));
        } catch (e) {}

        var t = fireText();
        if (t.indexOf("roaring") !== -1) return 4;
        if (t.indexOf("burning") !== -1) return 3;
        if (t.indexOf("flickering") !== -1) return 2;
        if (t.indexOf("smolder") !== -1) return 1;
        return 0;
    }

    function fireImageState() {
        var v = fireValue();
        if (v <= 0) return "out";
        if (v >= 4) return "roaring";
        return "flickering";
    }

    function temperatureText() {
        try {
            var t = $SM.get("game.temperature.text");
            if (typeof t === "string" && t.trim()) return t.trim().toLowerCase();
        } catch (e) {}
        return "unknown";
    }

    function temperatureValue() {
        try {
            var v = Number($SM.get("game.temperature.value"));
            if (isFinite(v)) return Math.max(0, Math.min(4, v));
        } catch (e) {}

        var t = temperatureText();
        if (t.indexOf("hot") !== -1) return 4;
        if (t.indexOf("warm") !== -1) return 3;
        if (t.indexOf("mild") !== -1) return 2;
        if (t.indexOf("cold") !== -1) return 1;
        return 0;
    }

    function spreadRisk() {
        var pct = Math.round(((fireValue() * 0.65) + (temperatureValue() * 0.35)) / 4 * 100);
        pct = Math.max(0, Math.min(100, pct));

        var desc = "none";
        if (pct >= 85) desc = "critical";
        else if (pct >= 65) desc = "high";
        else if (pct >= 40) desc = "moderate";
        else if (pct >= 15) desc = "low";

        return { percent: pct, description: desc };
    }

    function renderFire() {
        var state = fireImageState();
        var risk = spreadRisk();

        setPanel(
            "fire",
            FIRE_IMAGES[state],
            [
                "state: " + state,
                "temperature: " + temperatureText(),
                "spread risk: " + risk.percent + "% (" + risk.description + ")"
            ],
            true,
            risk.percent
        );
    }

    // ========================================================
    // VILLAGE / OUTSIDE
    // ========================================================
    function buildingAmount(key) {
        try {
            return Number($SM.get('game.buildings["' + key + '"]') || 0);
        } catch (e) {
            return 0;
        }
    }

    function population() {
        try {
            return Number($SM.get("game.population") || 0);
        } catch (e) {
            return 0;
        }
    }

    function villageStats() {
        var huts = buildingAmount("hut");
        var lodges = buildingAmount("lodge");

        var shops = [
            "trading post",
            "tannery",
            "smokehouse",
            "workshop",
            "steelworks",
            "armoury",
            "iron mine",
            "coal mine",
            "sulphur mine"
        ].reduce(function (n, name) {
            return n + (buildingAmount(name) > 0 ? 1 : 0);
        }, 0);

        var pop = population();
        var score = huts + lodges * 2 + shops * 2 + Math.floor(pop / 20);

        return {
            huts: huts,
            lodges: lodges,
            shops: shops,
            population: pop,
            score: score
        };
    }

    window.TrialVersion1VillageStageOverride =
        window.TrialVersion1VillageStageOverride || "auto";

    function villageStage(s) {
        if (window.TrialVersion1VillageStageOverride !== "auto") {
            return Number(window.TrialVersion1VillageStageOverride) || 1;
        }

        if (s.score >= 18 || s.huts >= 10 || s.lodges >= 3 || s.shops >= 5) return 4;
        if (s.score >= 11 || s.huts >= 6 || s.lodges >= 2 || s.shops >= 3) return 3;
        if (s.score >= 5 || s.huts >= 3 || s.shops >= 1) return 2;
        return 1;
    }

    function villageStageLabel(stage) {
        return {
            1: "early camp",
            2: "small village",
            3: "established settlement",
            4: "advanced settlement"
        }[stage] || "unknown";
    }

    window.setTrialVillageStage = function (stage) {
        if (stage === "auto") {
            window.TrialVersion1VillageStageOverride = "auto";
            return;
        }

        var n = Number(stage);
        if (![1,2,3,4].includes(n)) {
            console.error('Use "auto" or 1, 2, 3, 4.');
            return;
        }
        window.TrialVersion1VillageStageOverride = n;
    };

    function renderVillage() {
        var s = villageStats();
        var stage = villageStage(s);

        setPanel(
            "village",
            VILLAGE_IMAGES[stage],
            [
                "stage: " + villageStageLabel(stage),
                "huts/lodges: " + s.huts + " / " + s.lodges,
                "worker areas: " + s.shops,
                "population: " + s.population
            ],
            false,
            0
        );
    }

    // ========================================================
    // ONE ACTIVE-MODULE UPDATE LOOP
    // ========================================================
    function updateCombinedVisuals() {
        try {
            if (Engine.activeModule === Room) {
                renderFire();
                return;
            }

            if (Engine.activeModule === Outside) {
                renderVillage();
                return;
            }

            if (Engine.activeModule === Path) {
                renderCharacter();
                return;
            }
        } catch (e) {}

        hidePanel();
    }

    createSharedPanel();

    window.TrialVersion1CombinedVisualsTimer =
        window.setInterval(updateCombinedVisuals, 250);

    updateCombinedVisuals();

    // ========================================================
    // REMOVE
    // ========================================================
    window.removeTrialVersion1CombinedVisuals = function () {
        if (window.TrialVersion1CombinedVisualsTimer) {
            window.clearInterval(window.TrialVersion1CombinedVisualsTimer);
        }

        var panel = document.getElementById("trial-v1-shared-panel");
        if (panel) panel.remove();

        var armourControl = document.getElementById("trial-v1-combined-armour-control");
        if (armourControl) armourControl.remove();

        $('[data-trial-combined-hidden="true"]')
            .css("visibility", "")
            .removeAttr("data-trial-combined-hidden");

        if (originalGetMaxHealth) {
            World.getMaxHealth = originalGetMaxHealth;
        }

        window.TrialVersion1CombinedVisualsInstalled = false;

        console.log("Trial Version #1 Combined Visuals removed.");
    };

    console.log("Trial Version #1 Combined Visuals installed.");
})();


// ============================================================
// TRIAL VERSION #1
// Flight Crystal + Custom S Map Location
//
// WHAT THIS DOES
// - Leaves the normal generated world intact.
// - Adds ONE extra "$" onto an otherwise empty terrain tile.
// - The custom S is stored permanently at its chosen coordinates.
// - Reaching that exact S opens a Flight Crystal event.
// - Taking the Flight Crystal permanently unlocks flight.
// - The crystal is stored as permanent custom save-state and cannot be lost.
// - Once obtained, A Dusty Path gains a Flight ON/OFF button.
//
// FLIGHT ON:
// - no cured meat consumption while moving
// - no water consumption while moving
// - no random enemy encounters
// - flies over normal landmark/set-piece encounters
// - village still works normally so you can return home
// - if Flight is ON, you can embark without cured meat
//
// IMPORTANT:
// The normal game already uses "S" for its Sulphur Mine.
// This mod DOES NOT replace the normal Sulphur Mine.
// It adds one custom "$" marker and recognizes the Flight Crystal site by its exact
// saved coordinates.
//
// Remove the runtime mod with:
// removeTrialVersion1FlightCrystal()
//
// Useful console commands:
// TrialFlightCrystal.status()
// TrialFlightCrystal.revealSite()
// TrialFlightCrystal.flight(true)
// TrialFlightCrystal.flight(false)
// ============================================================

(function () {
    "use strict";

    if (window.TrialVersion1FlightCrystalInstalled) {
        console.log("Trial Version #1 Flight Crystal system is already installed.");
        return;
    }

    if (typeof window.$ === "undefined" ||
        typeof window.$SM === "undefined" ||
        typeof window.World === "undefined" ||
        typeof window.Path === "undefined" ||
        typeof window.Events === "undefined") {
        console.error("A Dark Room has not finished loading yet.");
        return;
    }

    window.TrialVersion1FlightCrystalInstalled = true;

    var $ = window.$;
    var $SM = window.$SM;
    var World = window.World;
    var Path = window.Path;
    var Events = window.Events;
    var Notifications = window.Notifications;
    var Button = window.Button;

    var originals = {
        doSpace: World.doSpace,
        useSupplies: World.useSupplies,
        checkFight: World.checkFight,
        updateBagSpace: Path.updateBagSpace
    };

    var EMPTY_TERRAIN = {
        ".": true,
        ",": true,
        ";": true
    };

    // ------------------------------------------------------------
    // Persistent state helpers
    // ------------------------------------------------------------
    function getState(path, fallback) {
        var value;

        try {
            value = $SM.get("game.flightCrystal." + path);
        } catch (e) {
            value = undefined;
        }

        return (typeof value === "undefined" || value === null)
            ? fallback
            : value;
    }

    function setState(path, value) {
        $SM.set("game.flightCrystal." + path, value);
    }

    function hasCrystal() {
        return getState("obtained", false) === true;
    }

    function flightEnabled() {
        return hasCrystal() &&
               getState("flightEnabled", false) === true;
    }

    function getSite() {
        var site = getState("site", null);

        if (Array.isArray(site) &&
            site.length === 2 &&
            typeof site[0] === "number" &&
            typeof site[1] === "number") {
            return site;
        }

        return null;
    }

    function samePosition(a, b) {
        return Array.isArray(a) &&
               Array.isArray(b) &&
               a.length >= 2 &&
               b.length >= 2 &&
               a[0] === b[0] &&
               a[1] === b[1];
    }

    // ------------------------------------------------------------
    // Choose a new EMPTY terrain tile without disturbing anything
    // generated by the original game.
    //
    // Custom shrine is placed 14-18 spaces from the village so it
    // cannot replace the normal sulphur mine at its normal 10-space
    // generation distance.
    // ------------------------------------------------------------
    function chooseCrystalSite(map) {
        if (!map || !map.length) return null;

        var village = World.VILLAGE_POS || [30, 30];
        var candidates = [];

        for (var x = 0; x < map.length; x++) {
            if (!map[x]) continue;

            for (var y = 0; y < map[x].length; y++) {
                var tile = map[x][y];

                if (!EMPTY_TERRAIN[tile]) continue;

                var dx = x - village[0];
                var dy = y - village[1];

                // Manhattan distance matches the grid movement nicely.
                var distance = Math.abs(dx) + Math.abs(dy);

                if (distance >= 14 && distance <= 18) {
                    candidates.push([x, y]);
                }
            }
        }

        if (!candidates.length) {
            // Fallback: use any empty terrain tile at least 8 spaces away.
            for (var fx = 0; fx < map.length; fx++) {
                if (!map[fx]) continue;

                for (var fy = 0; fy < map[fx].length; fy++) {
                    var ftile = map[fx][fy];

                    if (!EMPTY_TERRAIN[ftile]) continue;

                    var fdx = fx - village[0];
                    var fdy = fy - village[1];
                    var fdistance = Math.abs(fdx) + Math.abs(fdy);

                    if (fdistance >= 8) {
                        candidates.push([fx, fy]);
                    }
                }
            }
        }

        if (!candidates.length) return null;

        return candidates[Math.floor(Math.random() * candidates.length)];
    }

    // ------------------------------------------------------------
    // CLEANUP FOR EARLY "$" SHRINE BUG
    //
    // An earlier version accidentally moved the shrine every second,
    // leaving many "$" characters behind. "$" is not a native ADR map
    // tile, so we can safely clean those leftovers.
    //
    // We preserve ONE "$" at the saved Flight Crystal site and restore
    // every other accidental "$" to the most common adjacent terrain.
    // ------------------------------------------------------------
    function repairDuplicateDollarShrines() {
        var world;

        try {
            world = $SM.get("game.world");
        } catch (e) {
            return false;
        }

        if (!world || !world.map || !world.map.length) {
            return false;
        }

        var map = world.map;
        var site = getSite();

        function replacementTerrain(x, y) {
            var counts = {
                ".": 0,
                ",": 0,
                ";": 0
            };

            var dirs = [
                [1, 0],
                [-1, 0],
                [0, 1],
                [0, -1]
            ];

            dirs.forEach(function (d) {
                var nx = x + d[0];
                var ny = y + d[1];

                if (nx >= 0 &&
                    nx < map.length &&
                    map[nx] &&
                    ny >= 0 &&
                    ny < map[nx].length) {

                    var tile = map[nx][ny];

                    if (typeof counts[tile] === "number") {
                        counts[tile]++;
                    }
                }
            });

            var best = ".";
            var bestCount = -1;

            Object.keys(counts).forEach(function (tile) {
                if (counts[tile] > bestCount) {
                    best = tile;
                    bestCount = counts[tile];
                }
            });

            return best;
        }

        var changed = false;

        for (var x = 0; x < map.length; x++) {
            if (!map[x]) continue;

            for (var y = 0; y < map[x].length; y++) {
                if (map[x][y] !== "$") continue;

                // Keep only the one saved Flight Crystal site.
                if (site &&
                    x === site[0] &&
                    y === site[1]) {
                    continue;
                }

                map[x][y] = replacementTerrain(x, y);
                changed = true;
            }
        }

        if (changed) {
            $SM.set("game.world.map", map);

            try {
                if (World.state && World.state.map) {
                    World.state.map = map;

                    if (typeof World.drawMap === "function") {
                        World.drawMap();
                    }
                }
            } catch (e) {}

            console.log(
                "Flight Crystal repair: removed duplicate $ shrine markers."
            );
        }

        return changed;
    }

    // ------------------------------------------------------------
    // Add the extra $ after normal world generation already exists.
    // ------------------------------------------------------------
    function ensureCrystalSite() {
        var world;

        try {
            world = $SM.get("game.world");
        } catch (e) {
            return false;
        }

        if (!world || !world.map || !world.map.length) {
            return false;
        }

        var map = world.map;
        var site = getSite();

        if (!site) {
            site = chooseCrystalSite(map);

            if (!site) return false;

            setState("site", site);
            setState("originalTile", map[site[0]][site[1]]);
            setState("obtained", false);
            setState("flightEnabled", false);
        }

        var x = site[0];
        var y = site[1];

        if (!map[x] || typeof map[x][y] === "undefined") {
            return false;
        }

        // If the map has somehow been regenerated and this old coordinate
        // is now a real landmark, do NOT overwrite that landmark.
        if (!hasCrystal() &&
            map[x][y] !== "$" &&
            !EMPTY_TERRAIN[map[x][y]]) {

            var replacement = chooseCrystalSite(map);

            if (!replacement) return false;

            site = replacement;
            x = site[0];
            y = site[1];

            setState("site", site);
            setState("originalTile", map[x][y]);
        }

        // The site remains marked $ before and after collection.
        // Exact coordinates distinguish it from the normal sulphur mine.
        map[x][y] = "$";
        $SM.set("game.world.map", map);

        // Keep the live expedition map synchronized too.
        try {
            if (World.state && World.state.map &&
                World.state.map[x]) {
                World.state.map[x][y] = "$";
            }
        } catch (e) {}

        return true;
    }

    // ------------------------------------------------------------
    // Grant permanent crystal
    // ------------------------------------------------------------
    function grantCrystal() {
        setState("obtained", true);
        setState("flightEnabled", false);

        try {
            if (typeof window.Engine !== "undefined" &&
                typeof window.Engine.saveState === "function") {
                window.Engine.saveState();
            }
        } catch (e) {}

        refreshFlightButton();

        if (Notifications && Notifications.notify) {
            Notifications.notify(
                null,
                "the Flight Crystal hums softly. it feels bound to you."
            );
        }

        console.log("Flight Crystal permanently obtained.");
    }

    // ------------------------------------------------------------
    // Crystal event
    // ------------------------------------------------------------
    var crystalEvent = {
        title: "A Shimmering Shrine",
        scenes: {
            start: {
                text: [
                    "a broken stone shrine rises from the dust.",
                    "something pale-blue floats above its center.",
                    "the air bends around it. the crystal does not fall."
                ],
                buttons: {
                    take: {
                        text: "take the Flight Crystal",
                        onClick: function () {
                            grantCrystal();

                            try {
                                Events.endEvent();
                            } catch (e) {}
                        }
                    },
                    leave: {
                        text: "leave it",
                        nextScene: "end"
                    }
                }
            }
        }
    };

    function openCrystalEvent() {
        if (hasCrystal()) {
            if (Notifications && Notifications.notify) {
                Notifications.notify(
                    null,
                    "the empty shrine is silent."
                );
            }
            return;
        }

        try {
            if (typeof Events.activeEvent === "function" &&
                Events.activeEvent()) {
                return;
            }
        } catch (e) {}

        Events.startEvent(crystalEvent);
    }

    // ------------------------------------------------------------
    // World interaction interception
    // ------------------------------------------------------------
    World.doSpace = function () {
        var site = getSite();

        // The custom shrine always gets first priority.
        if (site &&
            World.curPos &&
            samePosition(World.curPos, site)) {
            openCrystalEvent();
            return;
        }

        if (flightEnabled()) {
            var currentTile = null;

            try {
                if (World.state &&
                    World.state.map &&
                    World.state.map[World.curPos[0]]) {
                    currentTile =
                        World.state.map[World.curPos[0]][World.curPos[1]];
                }
            } catch (e) {}

            // The village should still send the player home normally.
            if (World.TILE &&
                currentTile === World.TILE.VILLAGE) {
                return originals.doSpace.apply(World, arguments);
            }

            // While flying, all other landmark encounters are passed over.
            return;
        }

        return originals.doSpace.apply(World, arguments);
    };

    // No food/water expenditure while flying.
    World.useSupplies = function () {
        if (flightEnabled()) {
            return true;
        }

        return originals.useSupplies.apply(World, arguments);
    };

    // No random encounters while flying.
    World.checkFight = function () {
        if (flightEnabled()) {
            return;
        }

        return originals.checkFight.apply(World, arguments);
    };

    // ------------------------------------------------------------
    // Flight ON/OFF control on A Dusty Path
    // ------------------------------------------------------------
    function toggleFlight(forceValue) {
        if (!hasCrystal()) {
            return false;
        }

        var enabled =
            typeof forceValue === "boolean"
                ? forceValue
                : !flightEnabled();

        setState("flightEnabled", enabled);

        refreshFlightButton();

        try {
            if (typeof Path.updateBagSpace === "function") {
                Path.updateBagSpace();
            }
        } catch (e) {}

        if (Notifications && Notifications.notify) {
            Notifications.notify(
                null,
                enabled
                    ? "the Flight Crystal lifts you from the ground."
                    : "the crystal dims. your feet return to the dust."
            );
        }

        return enabled;
    }

    function createFlightButton() {
        if (!hasCrystal()) {
            $("#trial-flight-crystal-control").remove();
            return;
        }

        if ($("#trial-flight-crystal-control").length) {
            return;
        }

        var pathPanel = $("#pathPanel");

        if (!pathPanel.length) return;

        var holder = $("<div>")
            .attr("id", "trial-flight-crystal-control")
            .css({
                marginTop: "12px",
                width: "150px",
                fontFamily: "serif"
            });

        var status = $("<div>")
            .attr("id", "trial-flight-crystal-status")
            .text("Flight Crystal")
            .css({
                marginBottom: "4px",
                fontSize: "12px"
            });

        var button = $("<div>")
            .attr("id", "trial-flight-toggle")
            .addClass("button")
            .css({
                width: "130px",
                textAlign: "center",
                cursor: "pointer",
                userSelect: "none"
            })
            .on("click", function () {
                toggleFlight();
            });

        holder.append(status);
        holder.append(button);

        var embark = $("#embarkButton");

        if (embark.length) {
            holder.insertAfter(embark);
        } else {
            pathPanel.append(holder);
        }
    }

    function refreshFlightButton() {
        createFlightButton();

        var button = $("#trial-flight-toggle");

        if (!button.length) return;

        button.text(
            flightEnabled()
                ? "flight: ON"
                : "flight: OFF"
        );
    }

    // If Flight is active, allow departure even with zero cured meat.
    if (typeof originals.updateBagSpace === "function") {
        Path.updateBagSpace = function () {
            var result =
                originals.updateBagSpace.apply(Path, arguments);

            if (flightEnabled() &&
                $("#embarkButton").length &&
                Button &&
                typeof Button.setDisabled === "function") {
                Button.setDisabled(
                    $("#embarkButton"),
                    false
                );
            }

            refreshFlightButton();

            return result;
        };
    }

    // ------------------------------------------------------------
    // Site reveal helper for testing
    // ------------------------------------------------------------
    function revealSite() {
        ensureCrystalSite();

        var site = getSite();
        if (!site) return false;

        var world;

        try {
            world = $SM.get("game.world");
        } catch (e) {
            return false;
        }

        if (!world || !world.mask) return false;

        var mask = world.mask;

        // Reveal a small radius around the shrine.
        for (var dx = -2; dx <= 2; dx++) {
            for (var dy = -2; dy <= 2; dy++) {
                if (Math.abs(dx) + Math.abs(dy) > 2) continue;

                var x = site[0] + dx;
                var y = site[1] + dy;

                if (x >= 0 &&
                    mask[x] &&
                    y >= 0 &&
                    y < mask[x].length) {
                    mask[x][y] = true;
                }
            }
        }

        $SM.set("game.world.mask", mask);

        try {
            if (World.state && World.state.mask) {
                World.state.mask = mask;

                if (typeof World.drawMap === "function") {
                    World.drawMap();
                }
            }
        } catch (e) {}

        console.log(
            "Flight Crystal $ revealed at:",
            site
        );

        return true;
    }

    // ------------------------------------------------------------
    // Keep custom site and permanent state alive across redraws.
    // ------------------------------------------------------------
    window.TrialVersion1FlightCrystalTimer =
        window.setInterval(function () {
            repairDuplicateDollarShrines();
            ensureCrystalSite();

            if (hasCrystal()) {
                // This makes the permanent unlock authoritative even if some
                // other code changes transient UI or world state.
                setState("obtained", true);
            }

            refreshFlightButton();
        }, 1000);

    // ------------------------------------------------------------
    // Public helper object
    // ------------------------------------------------------------
    window.TrialFlightCrystal = {
        status: function () {
            var result = {
                site: getSite(),
                obtained: hasCrystal(),
                flightEnabled: flightEnabled()
            };

            console.log(result);
            return result;
        },

        revealSite: revealSite,

        repairMap: repairDuplicateDollarShrines,

        flight: function (on) {
            if (typeof on === "boolean") {
                return toggleFlight(on);
            }

            return toggleFlight();
        }
    };

    // ------------------------------------------------------------
    // Remove runtime hooks.
    // NOTE: permanent crystal save-state is intentionally NOT erased.
    // ------------------------------------------------------------
    window.removeTrialVersion1FlightCrystal = function () {
        if (window.TrialVersion1FlightCrystalTimer) {
            window.clearInterval(
                window.TrialVersion1FlightCrystalTimer
            );
        }

        World.doSpace = originals.doSpace;
        World.useSupplies = originals.useSupplies;
        World.checkFight = originals.checkFight;

        if (originals.updateBagSpace) {
            Path.updateBagSpace =
                originals.updateBagSpace;
        }

        $("#trial-flight-crystal-control").remove();

        window.TrialVersion1FlightCrystalInstalled =
            false;

        console.log(
            "Flight Crystal runtime mod removed. Permanent save-state was kept."
        );
    };

    repairDuplicateDollarShrines();
    ensureCrystalSite();
    refreshFlightButton();

    console.log("Trial Version #1 Flight Crystal system installed.");
    console.log("Normal world landmarks were preserved.");
})();
